// Lê o binário de config/limiares.json (nó "Ler Limiares", campo binário "data")
// e monta a entrada normalizada a partir do que o Trigger recebeu. Este nó
// NUNCA inventa valores: se o payload não for parseável como objeto JSON,
// ele segue adiante como {} + parse_error=true (o próximo nó -- validar() de
// contracts/guardrail.js -- vai reportar todos os campos como ausentes e
// marcar requer_humano, nunca vai supor um valor).
const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
const limiares = JSON.parse(buf.toString('utf8'));

const entrada = $('Trigger').first().json;
const origensValidas = ['mqtt', 'webhook', 'validacao'];
const origem = origensValidas.includes(entrada.origem) ? entrada.origem : 'webhook';

let payload = entrada.payload;
let payload_obj;
let parse_error = false;

if (typeof payload === 'string') {
  try {
    const parsed = JSON.parse(payload);
    if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) {
      payload_obj = parsed;
    } else {
      payload_obj = {};
      parse_error = true;
    }
  } catch (e) {
    payload_obj = {};
    parse_error = true;
  }
} else if (payload && typeof payload === 'object' && !Array.isArray(payload)) {
  payload_obj = payload;
} else {
  payload_obj = {};
  parse_error = true;
}

const id_para_query = (typeof payload_obj.id_maquina === 'string' && payload_obj.id_maquina.length > 0)
  ? payload_obj.id_maquina
  : null;

return [{
  json: {
    limiares,
    origem,
    payload_obj,
    parse_error,
    id_para_query,
    payload_bruto_original: payload === undefined ? null : payload,
    inicio_ms: Date.now(),
  },
}];

/*
 * Guardrail determinístico do CP5 — implementação de referência.
 *
 * Este arquivo é a fonte da verdade da lógica que roda nos nós Code do WF-10
 * ("validar" e "guardrail") e no nó "consolidar". Os nós do n8n copiam estas
 * funções; os testes (guardrail.test.js) garantem o comportamento.
 *
 * Princípio: valor ausente ou inválido vira null e é reportado — nunca 0.
 */

const ORDEM = ['NORMAL', 'ATENCAO', 'CRITICO'];
const ESPECIALISTA_DE = {
  temperatura: 'manutencao', vibracao: 'manutencao',
  tensao: 'energia', corrente: 'energia', fator_potencia: 'energia',
  eficiencia: 'producao',
};

const maxStatus = (...lista) =>
  lista.filter(s => ORDEM.includes(s))
       .reduce((a, b) => (ORDEM.indexOf(b) > ORDEM.indexOf(a) ? b : a), 'NORMAL');

/**
 * Valida e normaliza o payload bruto.
 * @param {object} bruto    payload recebido (MQTT ou webhook)
 * @param {object} limiares conteúdo de config/limiares.json
 * @param {object|null} nominais linha da tabela maquinas (null se desconhecida)
 */
function validar(bruto, limiares, nominais) {
  const payload = (bruto && typeof bruto === 'object' && !Array.isArray(bruto)) ? bruto : {};
  const campos = limiares.campos_obrigatorios.filter(c => c !== 'id_maquina');
  const permitidos = new Set([...limiares.campos_obrigatorios, 'ts', 'msg_id', 'uptime_s']);

  const idBruto = payload.id_maquina;
  const idInvalido = typeof idBruto !== 'string' || !new RegExp(limiares.id_maquina_regex).test(idBruto);

  const valores = {};
  const campos_ausentes = [];
  const tipo_invalido = [];
  const fora_faixa_fisica = [];

  for (const c of campos) {
    const v = payload[c];
    if (v === undefined || v === null || v === '') { campos_ausentes.push(c); valores[c] = null; continue; }
    if (typeof v !== 'number' || !Number.isFinite(v)) { tipo_invalido.push(c); valores[c] = null; continue; }
    const f = limiares.faixa_fisica[c];
    if (f && (v < f.min || v > f.max)) { fora_faixa_fisica.push(c); valores[c] = null; continue; }
    valores[c] = v;
  }

  valores.eficiencia = (valores.taxa_producao !== null && valores.taxa_producao_esperada)
    ? round2(valores.taxa_producao / valores.taxa_producao_esperada * 100)
    : null;

  const maquina_conhecida = !!nominais;
  const validacao = {
    ok: !idInvalido && maquina_conhecida && !campos_ausentes.length && !tipo_invalido.length && !fora_faixa_fisica.length,
    campos_ausentes, tipo_invalido, fora_faixa_fisica,
    id_invalido: idInvalido,
    maquina_conhecida,
    campos_extras: Object.keys(payload).filter(k => !permitidos.has(k)),
  };

  return {
    id_leitura: null,
    // id inválido nunca é propagado como texto livre (defesa contra prompt injection)
    id_maquina: idInvalido ? 'ID_INVALIDO' : idBruto,
    ts: typeof payload.ts === 'string' && !isNaN(Date.parse(payload.ts)) ? new Date(payload.ts).toISOString() : new Date().toISOString(),
    msg_id: Number.isInteger(payload.msg_id) ? payload.msg_id : null,
    valores,
    nominais: nominais || null,
    validacao,
  };
}

function classificar(regra, valor, cfg, nominais) {
  let x = valor;
  if (regra === 'desvio_percentual_nominal' || regra === 'percentual_nominal') {
    const nominal = nominais && nominais[cfg.nominal];
    if (!nominal) return { status: null, x: null };
    x = regra === 'desvio_percentual_nominal'
      ? Math.abs(valor - nominal) / nominal * 100
      : valor / nominal * 100;
  }
  const acima = regra !== 'abaixo';
  const passa = (lim) => (acima ? x > lim : x < lim);
  if (passa(cfg.critico)) return { status: 'CRITICO', x: round2(x), limite: cfg.critico };
  if (passa(cfg.atencao)) return { status: 'ATENCAO', x: round2(x), limite: cfg.atencao };
  return { status: 'NORMAL', x: round2(x) };
}

/**
 * Aplica os limiares. Recebe a saída de validar() e devolve o objeto guardrail.
 */
function guardrail(leitura, limiares) {
  const por_especialista = { manutencao: 'NORMAL', producao: 'NORMAL', energia: 'NORMAL' };
  const violacoes = [];

  for (const [esp, def] of Object.entries(limiares.especialistas)) {
    for (const [grandeza, cfg] of Object.entries(def.grandezas)) {
      const v = leitura.valores[grandeza];
      if (v === null || v === undefined) continue;
      const r = classificar(cfg.regra, v, cfg, leitura.nominais);
      if (!r.status) continue;
      por_especialista[esp] = maxStatus(por_especialista[esp], r.status);
      if (r.status !== 'NORMAL') {
        violacoes.push({ especialista: esp, grandeza, valor: r.x, limite: r.limite, status: r.status });
      }
    }
  }

  const val = leitura.validacao;
  const sensor_fault = val.tipo_invalido.length > 0 || val.fora_faixa_fisica.length > 0;
  const requer_humano = !val.ok;
  let status = maxStatus(...Object.values(por_especialista));
  if (requer_humano) status = maxStatus(status, 'ATENCAO');

  return { status, sensor_fault, requer_humano, por_especialista, violacoes };
}

/**
 * Consolida a resposta do Supervisor (LLM) com o guardrail.
 * statusLlm pode ser null (LLM não chamado ou falhou).
 * especialistasRequeremHumano: true se algum parecer veio com dados_insuficientes.
 */
function consolidar(leitura, statusLlm, limiares, especialistasRequeremHumano = false) {
  const g = leitura.guardrail;
  const status_llm = ORDEM.includes(statusLlm) ? statusLlm : null;
  const requer_humano = g.requer_humano || !!especialistasRequeremHumano;
  let status_final = maxStatus(g.status, status_llm);
  if (requer_humano) status_final = maxStatus(status_final, 'ATENCAO');

  let acoes = [...limiares.acoes_por_status[status_final]];
  if (requer_humano) acoes = acoes.filter(a => a !== 'TRELLO');

  return { status_guardrail: g.status, status_llm, status_final, sensor_fault: g.sensor_fault, requer_humano, acoes_previstas: acoes };
}

function round2(n) { return Math.round(n * 100) / 100; }

// --- Fiação (WF-10, nó "Validar e Guardrail") -------------------------------
// Nada acima desta linha foi escrito à mão: é o conteúdo literal de
// contracts/guardrail.js, injetado por n8n/build.js. Este trecho só chama as
// funções acima e formata a saída no shape de contracts/leitura.schema.json.
const prep = $('Preparar Payload').first().json;
const nominaisRow = $input.first().json || {};
const nominais = (nominaisRow.tensao_nominal !== undefined && nominaisRow.tensao_nominal !== null)
  ? {
      descricao: nominaisRow.descricao,
      tensao_nominal: Number(nominaisRow.tensao_nominal),
      corrente_nominal: Number(nominaisRow.corrente_nominal),
    }
  : null;

const bruto = prep.parse_error ? {} : prep.payload_obj;
const leitura = validar(bruto, prep.limiares, nominais);
leitura.origem = prep.origem;
leitura.guardrail = guardrail(leitura, prep.limiares);

return [{
  json: {
    leitura,
    payload_bruto_original: prep.payload_bruto_original,
    inicio_ms: prep.inicio_ms,
  },
}];

// Achata o objeto "leitura" (contracts/leitura.schema.json) nas colunas
// exatas da tabela leituras (db/01_schema.sql). id_maquina só é preenchida
// quando a máquina é conhecida (mantém a FK nullable); id_maquina_recebido
// sempre é preenchida (auditoria). Nada aqui decide severidade -- só mapeia
// nomes de campo para nomes de coluna.
const data = $input.first().json;
const leitura = data.leitura;
const g = leitura.guardrail;
const v = leitura.valores;

function toDatetimeMySQL(iso) {
  // "2026-09-28T10:00:00.000Z" -> "2026-09-28 10:00:00"
  return String(iso).slice(0, 19).replace('T', ' ');
}

return [{
  json: {
    id_maquina: leitura.validacao.maquina_conhecida ? leitura.id_maquina : null,
    id_maquina_recebido: leitura.id_maquina,
    ts: toDatetimeMySQL(leitura.ts),
    msg_id: leitura.msg_id,
    origem: leitura.origem,
    temperatura: v.temperatura,
    vibracao: v.vibracao,
    tensao: v.tensao,
    corrente: v.corrente,
    fator_potencia: v.fator_potencia,
    taxa_producao: v.taxa_producao,
    taxa_producao_esperada: v.taxa_producao_esperada,
    eficiencia: v.eficiencia,
    validacao: JSON.stringify(leitura.validacao),
    guardrail_status: g.status,
    sensor_fault: g.sensor_fault,
    requer_humano: g.requer_humano,
    payload_bruto: JSON.stringify(data.payload_bruto_original === undefined ? null : data.payload_bruto_original),
  },
}];

// SUPERVISOR (stub) -- T06/T07.
// Será substituído em T12 por um AI Agent real (Supervisor + 3 especialistas
// via toolWorkflow). Até lá: status_llm sempre null, pareceres sempre null.
//
// A função gerarFallbackOperador() abaixo é determinística (não chama LLM
// algum) e foi escrita para ser REAPROVEITÁVEL: em T12 ela deve virar o
// fallback usado quando o Supervisor real falhar/não responder a tempo --
// nesse caso o pipeline não pode ficar sem resumo_operador/justificativa.
function gerarFallbackOperador(leitura, limiares) {
  const rotulos = limiares.status.rotulos;
  const val = leitura.validacao;
  const g = leitura.guardrail;

  if (!val.ok) {
    const motivos = [];
    if (val.id_invalido) motivos.push('id_maquina inválido ou fora do padrão');
    if (!val.maquina_conhecida) motivos.push('máquina desconhecida (' + leitura.id_maquina + ')');
    if (val.campos_ausentes.length) motivos.push('campo(s) ausente(s): ' + val.campos_ausentes.join(', '));
    if (val.tipo_invalido.length) motivos.push('tipo inválido em: ' + val.tipo_invalido.join(', '));
    if (val.fora_faixa_fisica.length) motivos.push('fora da faixa física: ' + val.fora_faixa_fisica.join(', '));
    const motivoPrincipal = motivos[0] || 'validação falhou';
    const resumo_operador = ('Dados inconsistentes: ' + motivoPrincipal + '. Verificação humana necessária.').slice(0, 500);
    const justificativa = (
      'Verificação humana necessária. Motivo(s): ' + motivos.join('; ') + '. ' +
      'Guardrail determinístico (config/limiares.json): ' + rotulos[g.status] + '. ' +
      'Supervisor LLM não avaliado (stub T06/T07 -- será substituído em T12).'
    ).slice(0, 2000);
    return { resumo_operador, justificativa };
  }

  if (!g.violacoes.length) {
    return {
      resumo_operador: (leitura.id_maquina + ' em ' + rotulos[g.status] + ': nenhuma grandeza fora do limiar.').slice(0, 500),
      justificativa: (
        'Guardrail determinístico avaliou todas as grandezas dentro dos limiares configurados ' +
        '(config/limiares.json). Status: ' + rotulos[g.status] + '. ' +
        'Supervisor LLM não avaliado (stub T06/T07 -- será substituído em T12).'
      ).slice(0, 2000),
    };
  }

  const partes = g.violacoes.map((v) => v.grandeza + ' ' + v.valor + ' (limite ' + v.limite + ', ' + rotulos[v.status] + ')');
  const resumo_operador = (leitura.id_maquina + ' em ' + rotulos[g.status] + ': ' + partes.join('; ') + '.').slice(0, 500);
  const justificativa = (
    'Guardrail determinístico (config/limiares.json) classificou ' + leitura.id_maquina + ' como ' + rotulos[g.status] + '. ' +
    'Violações: ' + partes.join('; ') + '. ' +
    'Especialistas: manutenção=' + rotulos[g.por_especialista.manutencao] +
    ', produção=' + rotulos[g.por_especialista.producao] +
    ', energia=' + rotulos[g.por_especialista.energia] + '. ' +
    'Supervisor LLM não avaliado (stub T06/T07 -- será substituído em T12).'
  ).slice(0, 2000);
  return { resumo_operador, justificativa };
}

const insertResult = $('Inserir Leitura').first().json;
const anterior = $('Validar e Guardrail').first().json;
const limiares = $('Preparar Payload').first().json.limiares;

// options.detailedOutput:true no nó "Inserir Leitura" -> { sql, data: <ResultSetHeader> }.
// Sem detailedOutput cairia em {success:true} sem insertId nenhum (ver comentário no
// gerador do template). Checamos os dois formatos por robustez.
const insertId = (insertResult.data && insertResult.data.insertId !== undefined)
  ? insertResult.data.insertId
  : insertResult.insertId;

const leitura = Object.assign({}, anterior.leitura, { id_leitura: insertId });
const fallback = gerarFallbackOperador(leitura, limiares);

return [{
  json: {
    leitura,
    status_llm: null,
    pareceres: { manutencao: null, producao: null, energia: null },
    resumo_operador: fallback.resumo_operador,
    justificativa: fallback.justificativa,
    inicio_ms: anterior.inicio_ms,
  },
}];

